// Differential tests: random token sequences are parsed by the generated parser
// and by a hand-written reference, and the two must agree on everything that is
// observable: the result, the position of the first error, and the set of
// expected terminals at every step.
//
// The inputs are generated by a fixed-seed generator, so runs are reproducible.

/// Minimal deterministic generator (xorshift64*), to avoid a `rand` dependency.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }

    fn chance(&mut self, percent: usize) -> bool {
        self.below(100) < percent
    }
}

mod expr {
    // An expression grammar using every kind of precedence declaration:
    // `nonassoc`, `left` (two levels, one with two tokens), `right`, and a
    // pseudo-token for unary minus.
    use super::Rng;
    use ferrolith::{ParseError, grammar};

    #[derive(Debug, Clone, Copy, PartialEq)]
    enum Tok {
        Num(i64),
        Lt,
        Plus,
        Minus,
        Star,
        Caret,
        LParen,
        RParen,
    }

    grammar! {
        type Token = Tok;

        #[nonassoc(Lt)]
        #[left(Plus, Minus)]
        #[left(Star)]
        #[right(Caret)]
        #[right(UMinus)]

        #[start]
        fn expr() -> String {
            (Num(n))                    => n.to_string(),
            (l @ expr, Lt, r @ expr)    => format!("({l}<{r})"),
            (l @ expr, Plus, r @ expr)  => format!("({l}+{r})"),
            (l @ expr, Minus, r @ expr) => format!("({l}-{r})"),
            (l @ expr, Star, r @ expr)  => format!("({l}*{r})"),
            (l @ expr, Caret, r @ expr) => format!("({l}^{r})"),
            #[prec(UMinus)]
            (Minus, e @ expr)           => format!("(-{e})"),
            (LParen, e @ expr, RParen)  => format!("[{e}]"),
        }
    }

    const ALPHABET: [Tok; 8] = [
        Tok::Num(0),
        Tok::Lt,
        Tok::Plus,
        Tok::Minus,
        Tok::Star,
        Tok::Caret,
        Tok::LParen,
        Tok::RParen,
    ];

    fn name(t: Option<Tok>) -> &'static str {
        match t {
            None => "<eof>",
            Some(Tok::Num(_)) => "Num",
            Some(Tok::Lt) => "Lt",
            Some(Tok::Plus) => "Plus",
            Some(Tok::Minus) => "Minus",
            Some(Tok::Star) => "Star",
            Some(Tok::Caret) => "Caret",
            Some(Tok::LParen) => "LParen",
            Some(Tok::RParen) => "RParen",
        }
    }

    /// Reference recogniser: tracks which tokens may come next.
    ///
    /// `Lt` is the loosest operator and is non-associative, so two `Lt` at the
    /// same parenthesis depth are always chained: each depth allows one.
    #[derive(Clone)]
    struct Viable {
        want_operand: bool,
        /// One entry per open parenthesis plus the top level: `Lt` seen there.
        lt_seen: Vec<bool>,
    }

    impl Viable {
        fn new() -> Self {
            Viable {
                want_operand: true,
                lt_seen: vec![false],
            }
        }

        fn accepts(&self, t: Option<Tok>) -> bool {
            let nested = self.lt_seen.len() > 1;
            match (self.want_operand, t) {
                (true, Some(Tok::Num(_) | Tok::Minus | Tok::LParen)) => true,
                (true, _) => false,
                (false, Some(Tok::Plus | Tok::Minus | Tok::Star | Tok::Caret)) => true,
                (false, Some(Tok::Lt)) => !self.lt_seen.last().unwrap(),
                (false, Some(Tok::RParen)) => nested,
                (false, None) => !nested,
                (false, _) => false,
            }
        }

        fn advance(&mut self, t: Tok) {
            match t {
                Tok::Num(_) => self.want_operand = false,
                Tok::LParen => self.lt_seen.push(false),
                Tok::RParen => {
                    self.lt_seen.pop();
                }
                Tok::Lt => {
                    *self.lt_seen.last_mut().unwrap() = true;
                    self.want_operand = true;
                }
                Tok::Minus if self.want_operand => {}
                Tok::Plus | Tok::Minus | Tok::Star | Tok::Caret => self.want_operand = true,
            }
        }

        fn expected(&self) -> Vec<&'static str> {
            let mut names: Vec<_> = ALPHABET
                .iter()
                .map(|t| Some(*t))
                .chain([None])
                .filter(|t| self.accepts(*t))
                .map(name)
                .collect();
            names.sort();
            names
        }
    }

    /// Reference evaluator (precedence climbing), only run on valid inputs.
    struct Climber<'a> {
        tokens: &'a [Tok],
        pos: usize,
    }

    impl Climber<'_> {
        fn peek(&self) -> Option<Tok> {
            self.tokens.get(self.pos).copied()
        }

        // (level, right associative, symbol)
        fn binary(t: Option<Tok>) -> Option<(u8, bool, char)> {
            Some(match t? {
                Tok::Lt => (1, false, '<'),
                Tok::Plus => (2, false, '+'),
                Tok::Minus => (2, false, '-'),
                Tok::Star => (3, false, '*'),
                Tok::Caret => (4, true, '^'),
                _ => return None,
            })
        }

        fn expr(&mut self, min: u8) -> String {
            let mut lhs = self.unary();
            while let Some((level, right, sym)) = Self::binary(self.peek())
                && level >= min
            {
                self.pos += 1;
                let rhs = self.expr(if right { level } else { level + 1 });
                lhs = format!("({lhs}{sym}{rhs})");
            }
            lhs
        }

        // Unary minus binds tighter than every binary operator.
        fn unary(&mut self) -> String {
            match self.peek().unwrap() {
                Tok::Minus => {
                    self.pos += 1;
                    format!("(-{})", self.unary())
                }
                Tok::Num(n) => {
                    self.pos += 1;
                    n.to_string()
                }
                Tok::LParen => {
                    self.pos += 1;
                    let e = self.expr(1);
                    assert_eq!(self.peek(), Some(Tok::RParen));
                    self.pos += 1;
                    format!("[{e}]")
                }
                t => panic!("reference evaluator run on an invalid input: {t:?}"),
            }
        }
    }

    /// The reference verdict: the value, or the index of the first token that
    /// cannot follow (`tokens.len()` for the end of input) and what could.
    fn reference(tokens: &[Tok]) -> Result<String, (usize, Vec<&'static str>)> {
        let mut viable = Viable::new();
        for (i, t) in tokens.iter().enumerate() {
            if !viable.accepts(Some(*t)) {
                return Err((i, viable.expected()));
            }
            viable.advance(*t);
        }
        if !viable.accepts(None) {
            return Err((tokens.len(), viable.expected()));
        }
        let mut climber = Climber { tokens, pos: 0 };
        let value = climber.expr(1);
        assert_eq!(climber.pos, tokens.len());
        Ok(value)
    }

    /// Mostly follows the reference recogniser so that long valid inputs are
    /// common, with an occasional arbitrary token to produce errors anywhere.
    fn generate(rng: &mut Rng) -> Vec<Tok> {
        let max_len = rng.below(24);
        let mut viable = Viable::new();
        let mut tokens = vec![];
        while tokens.len() < max_len {
            if viable.accepts(None) && rng.chance(8) {
                break;
            }
            let mut t = ALPHABET[rng.below(ALPHABET.len())];
            if !rng.chance(4) {
                while !viable.accepts(Some(t)) {
                    t = ALPHABET[rng.below(ALPHABET.len())];
                }
            }
            if let Tok::Num(_) = t {
                t = Tok::Num(rng.below(10) as i64);
            }
            tokens.push(t);
            if viable.accepts(Some(t)) {
                viable.advance(t);
            } else {
                // Keep a few tokens after the error.
                for _ in 0..rng.below(3) {
                    tokens.push(ALPHABET[rng.below(ALPHABET.len())]);
                }
                break;
            }
        }
        tokens
    }

    fn sorted(mut names: Vec<&'static str>) -> Vec<&'static str> {
        names.sort();
        names
    }

    fn check_parse(tokens: &[Tok], expected: &Result<String, (usize, Vec<&'static str>)>) {
        match (parse(tokens.iter().copied()), expected) {
            (Ok(got), Ok(want)) => assert_eq!(&got, want, "input: {tokens:?}"),
            (
                Err(ParseError::UnexpectedToken {
                    token,
                    expected: got,
                    ..
                }),
                Err((at, want)),
            ) => {
                assert!(*at < tokens.len(), "input: {tokens:?}");
                assert_eq!(token, tokens[*at], "input: {tokens:?}");
                assert_eq!(&sorted(got), want, "input: {tokens:?}");
            }
            (Err(ParseError::UnexpectedEof { expected: got }), Err((at, want))) => {
                assert_eq!(*at, tokens.len(), "input: {tokens:?}");
                assert_eq!(&sorted(got), want, "input: {tokens:?}");
            }
            (got, want) => panic!("input: {tokens:?}\n got: {got:?}\nwant: {want:?}"),
        }
    }

    fn check_feed(tokens: &[Tok], expected: &Result<String, (usize, Vec<&'static str>)>) {
        let mut viable = Viable::new();
        let mut cp = start();
        for (i, t) in tokens.iter().map(|t| Some(*t)).chain([None]).enumerate() {
            let Checkpoint::InputNeeded(state) = cp else {
                panic!("input: {tokens:?}\nparser stopped before token {i}");
            };
            assert_eq!(
                sorted(state.expected_terminals()),
                viable.expected(),
                "input: {tokens:?}\nexpected terminals before token {i}"
            );
            cp = feed(state, t);
            match (&cp, expected) {
                (Checkpoint::Rejected(_, _), Err((at, _))) => {
                    assert_eq!(i, *at, "input: {tokens:?}\nrejected at the wrong token");
                    return;
                }
                (Checkpoint::Rejected(_, e), Ok(_)) => {
                    panic!("input: {tokens:?}\nvalid input rejected at token {i}: {e:?}")
                }
                (Checkpoint::Accepted(got), Ok(want)) => {
                    assert_eq!(i, tokens.len(), "input: {tokens:?}");
                    assert_eq!(got, want, "input: {tokens:?}");
                    return;
                }
                (Checkpoint::Accepted(got), Err(_)) => {
                    panic!("input: {tokens:?}\ninvalid input accepted as {got}")
                }
                (Checkpoint::InputNeeded(_), Err((at, _))) => {
                    assert!(i < *at, "input: {tokens:?}\ntoken {i} should be rejected");
                }
                (Checkpoint::InputNeeded(_), Ok(_)) => {
                    assert!(
                        i < tokens.len(),
                        "input: {tokens:?}\nnot accepted at the end"
                    );
                }
            }
            if let Some(t) = t {
                viable.advance(t);
            }
        }
    }

    #[test]
    fn known_groupings() {
        use Tok::*;
        let cases: [(&[Tok], &str); 8] = [
            (&[Num(1), Plus, Num(2), Star, Num(3)], "(1+(2*3))"),
            (&[Num(1), Star, Num(2), Plus, Num(3)], "((1*2)+3)"),
            (&[Num(1), Minus, Num(2), Minus, Num(3)], "((1-2)-3)"),
            (&[Num(1), Minus, Num(2), Plus, Num(3)], "((1-2)+3)"),
            (&[Num(2), Caret, Num(3), Caret, Num(2)], "(2^(3^2))"),
            (&[Minus, Num(2), Caret, Num(2)], "((-2)^2)"),
            (&[Num(1), Lt, Num(2), Plus, Num(3)], "(1<(2+3))"),
            (
                &[LParen, Num(1), Lt, Num(2), RParen, Lt, Num(3)],
                "([(1<2)]<3)",
            ),
        ];
        for (tokens, want) in cases {
            assert_eq!(parse(tokens.iter().copied()).unwrap(), want);
            assert_eq!(reference(tokens).unwrap(), want);
        }
    }

    #[test]
    fn random_inputs_agree_with_reference() {
        let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
        let (mut valid, mut invalid) = (0, 0);
        for _ in 0..20_000 {
            let tokens = generate(&mut rng);
            let expected = reference(&tokens);
            match expected {
                Ok(_) => valid += 1,
                Err(_) => invalid += 1,
            }
            check_parse(&tokens, &expected);
            check_feed(&tokens, &expected);
        }
        // The generator must exercise both outcomes substantially.
        assert!(valid > 2_000, "only {valid} valid inputs");
        assert!(invalid > 2_000, "only {invalid} invalid inputs");
    }
}

mod stmts {
    // Error recovery: a list of `expr ;` statements where a broken statement is
    // skipped up to its `;` and replaced by the error that broke it (bound with
    // `e @ error`). The reference works on the `;`-separated segments.
    use super::Rng;
    use ferrolith::{ParseError, grammar};

    #[derive(Debug, Clone, Copy, PartialEq)]
    enum Tok {
        Num(i64),
        Plus,
        Semi,
    }

    grammar! {
        type Token = Tok;

        #[start]
        fn program() -> Vec<Stmt> {
            (stmts @ star(stmt)) => stmts,
        }

        fn stmt() -> Stmt {
            (e @ expr, Semi)    => Ok(e),
            (e @ error, Semi)   => Err(Recovered::from(e)),
        }

        fn expr() -> i64 {
            (Num(n))                 => n,
            (l @ expr, Plus, Num(n)) => l + n,
        }
    }

    /// A statement: its value, or the error it was recovered from.
    type Stmt = Result<i64, Recovered>;

    /// The error bound by `e @ error`: the first token that could not continue
    /// the statement, and what could have.
    #[derive(Debug, Clone, PartialEq)]
    struct Recovered {
        token: Tok,
        expected: Vec<&'static str>,
    }

    impl From<ParseError<Tok>> for Recovered {
        fn from(e: ParseError<Tok>) -> Self {
            match e {
                ParseError::UnexpectedToken {
                    token, expected, ..
                } => Recovered {
                    token,
                    expected: sorted(expected),
                },
                // The end of input never ends a statement, so recovery cannot
                // complete there.
                ParseError::UnexpectedEof { .. } => unreachable!(),
            }
        }
    }

    /// How far a statement has got.
    #[derive(Clone, Copy, PartialEq)]
    enum Seg {
        /// Nothing yet, or just after a `;`.
        Start,
        /// After a number: `+` or `;` may follow.
        AfterNum(i64),
        /// After a `+`: a number must follow.
        AfterPlus(i64),
        /// An error was found: skipping to the next `;`.
        Broken,
    }

    impl Seg {
        fn advance(self, t: Tok) -> Seg {
            match (self, t) {
                (_, Tok::Semi) => Seg::Start,
                (Seg::Start, Tok::Num(n)) => Seg::AfterNum(n),
                (Seg::AfterNum(sum), Tok::Plus) => Seg::AfterPlus(sum),
                (Seg::AfterPlus(sum), Tok::Num(n)) => Seg::AfterNum(sum + n),
                _ => Seg::Broken,
            }
        }

        /// The terminals that can come next in a statement that is not broken.
        fn expected(self) -> Vec<&'static str> {
            match self {
                Seg::Start => vec!["<eof>", "Num"],
                Seg::AfterNum(_) => vec!["Plus", "Semi"],
                Seg::AfterPlus(_) => vec!["Num"],
                Seg::Broken => unreachable!(),
            }
        }

        fn accepts(self, t: Tok) -> bool {
            matches!(
                (self, t),
                (Seg::Start | Seg::AfterPlus(_), Tok::Num(_))
                    | (Seg::AfterNum(_), Tok::Plus | Tok::Semi)
            )
        }

        /// What the parser expects at the end of input, when it is an error.
        fn expected_at_eof(self) -> Option<Vec<&'static str>> {
            match self {
                Seg::Start => None,
                Seg::AfterNum(_) => Some(vec!["Plus", "Semi"]),
                Seg::AfterPlus(_) => Some(vec!["Num"]),
                Seg::Broken => Some(vec!["Semi"]),
            }
        }
    }

    fn reference(tokens: &[Tok]) -> Result<Vec<Stmt>, Vec<&'static str>> {
        let mut stmts = vec![];
        let mut seg = Seg::Start;
        // The first error of the current statement.
        let mut error: Option<Recovered> = None;
        for t in tokens {
            if seg != Seg::Broken && !seg.accepts(*t) {
                error = Some(Recovered {
                    token: *t,
                    expected: seg.expected(),
                });
            }
            if *t == Tok::Semi {
                stmts.push(match (error.take(), seg) {
                    (Some(e), _) => Err(e),
                    (None, Seg::AfterNum(sum)) => Ok(sum),
                    (None, _) => unreachable!(),
                });
            }
            seg = seg.advance(*t);
        }
        match seg.expected_at_eof() {
            None => Ok(stmts),
            Some(expected) => Err(expected),
        }
    }

    fn generate(rng: &mut Rng) -> Vec<Tok> {
        let len = rng.below(30);
        let mut seg = Seg::Start;
        let mut tokens = vec![];
        for _ in 0..len {
            // Mostly well-formed, so that statements complete and errors are
            // surrounded by valid input.
            let t = if rng.chance(15) {
                [Tok::Num(1), Tok::Plus, Tok::Semi][rng.below(3)]
            } else {
                match seg {
                    Seg::Start | Seg::AfterPlus(_) => Tok::Num(rng.below(10) as i64),
                    Seg::AfterNum(_) if rng.chance(50) => Tok::Plus,
                    _ => Tok::Semi,
                }
            };
            seg = seg.advance(t);
            tokens.push(t);
        }
        tokens
    }

    fn sorted(mut names: Vec<&'static str>) -> Vec<&'static str> {
        names.sort();
        names
    }

    #[test]
    fn random_inputs_agree_with_reference() {
        let mut rng = Rng(0xD1B5_4A32_D192_ED03);
        let (mut valid, mut recovered, mut invalid) = (0, 0, 0);
        for _ in 0..20_000 {
            let tokens = generate(&mut rng);
            let expected = reference(&tokens);
            match &expected {
                Ok(stmts) if stmts.iter().any(Result::is_err) => recovered += 1,
                Ok(_) => valid += 1,
                Err(_) => invalid += 1,
            }

            match (parse(tokens.iter().copied()), &expected) {
                (Ok(got), Ok(want)) => assert_eq!(&got, want, "input: {tokens:?}"),
                (Err(ParseError::UnexpectedEof { expected: got }), Err(want)) => {
                    assert_eq!(&sorted(got), want, "input: {tokens:?}")
                }
                (got, want) => panic!("input: {tokens:?}\n got: {got:?}\nwant: {want:?}"),
            }

            let mut seg = Seg::Start;
            let mut cp = start();
            for (i, t) in tokens.iter().enumerate() {
                let Checkpoint::InputNeeded(state) = cp else {
                    panic!("input: {tokens:?}\nparser stopped before token {i}");
                };
                cp = feed(state, Some(*t));
                seg = seg.advance(*t);
                let Checkpoint::InputNeeded(state) = &cp else {
                    panic!("input: {tokens:?}\nparser stopped at token {i}");
                };
                // `1 + ;` is only found broken at the `;` that also ends the
                // recovery, so the parser is skipping input exactly when the
                // reference is.
                assert_eq!(
                    state.is_recovering(),
                    seg == Seg::Broken,
                    "input: {tokens:?}\nrecovering after token {i}"
                );
            }
            let Checkpoint::InputNeeded(state) = cp else {
                unreachable!()
            };
            match (feed(state, None), &expected) {
                (Checkpoint::Accepted(got), Ok(want)) => {
                    assert_eq!(&got, want, "input: {tokens:?}")
                }
                (
                    Checkpoint::Rejected(_, ParseError::UnexpectedEof { expected: got }),
                    Err(want),
                ) => assert_eq!(&sorted(got), want, "input: {tokens:?}"),
                _ => panic!("input: {tokens:?}\n`feed` disagrees with the reference"),
            }
        }
        assert!(valid > 1_000, "only {valid} valid inputs");
        assert!(recovered > 1_000, "only {recovered} recovered inputs");
        assert!(invalid > 1_000, "only {invalid} invalid inputs");
    }
}

mod spans {
    // Payloads: every token carries its index range, and every node of the
    // result records the span the parser computed for it. Inputs are generated
    // from random trees, so the expected spans are known by construction.
    use super::Rng;
    use ferrolith::grammar;

    #[derive(Debug, Clone, Copy)]
    enum Tok {
        Num(i64),
        Plus,
        Star,
        LParen,
        RParen,
    }

    type Span = (usize, usize);

    fn merge(first: Span, last: Span) -> Span {
        (first.0, last.1)
    }

    fn node(text: String, span: Span) -> String {
        format!("{text}@{}..{}", span.0, span.1)
    }

    grammar! {
        #![parser_cfg(payload_merge = merge)]

        type Token = Tok;
        type Payload = Span;

        #[left(Plus)]
        #[left(Star)]

        #[start]
        fn expr() -> String {
            (Num(n))                   => node(n.to_string(), _1_payload),
            (l @ expr, Plus, r @ expr) => node(format!("({l}+{r})"), _payload),
            (l @ expr, Star, r @ expr) => node(format!("({l}*{r})"), _payload),
            (LParen, e @ expr, RParen) => node(format!("[{e}]"), _payload),
        }
    }

    /// Appends the tokens of a random expression at the given precedence level
    /// (0: sum, 1: product, 2: atom) and returns its expected rendering.
    fn generate(rng: &mut Rng, level: u8, depth: u8, tokens: &mut Vec<Tok>) -> String {
        let start = tokens.len();
        if level == 2 {
            if depth < 4 && rng.chance(25) {
                tokens.push(Tok::LParen);
                let inner = generate(rng, 0, depth + 1, tokens);
                tokens.push(Tok::RParen);
                return node(format!("[{inner}]"), (start, tokens.len()));
            }
            let n = rng.below(10) as i64;
            tokens.push(Tok::Num(n));
            return node(n.to_string(), (start, tokens.len()));
        }

        let (op, sym) = if level == 0 {
            (Tok::Plus, '+')
        } else {
            (Tok::Star, '*')
        };
        // Left associative: each operand extends the node built so far.
        let mut lhs = generate(rng, level + 1, depth, tokens);
        for _ in 0..rng.below(3) {
            tokens.push(op);
            let rhs = generate(rng, level + 1, depth, tokens);
            lhs = node(format!("({lhs}{sym}{rhs})"), (start, tokens.len()));
        }
        lhs
    }

    #[test]
    fn random_trees_have_exact_spans() {
        let mut rng = Rng(0xA076_1D64_78BD_642F);
        for _ in 0..5_000 {
            let mut tokens = vec![];
            let want = generate(&mut rng, 0, 0, &mut tokens);
            let input = tokens.iter().enumerate().map(|(i, t)| (*t, (i, i + 1)));

            let got = parse(input.clone()).unwrap_or_else(|_| panic!("input: {tokens:?}"));
            assert_eq!(got, want, "input: {tokens:?}");

            let mut cp = start();
            for t in input.map(Some).chain([None]) {
                let Checkpoint::InputNeeded(state) = cp else {
                    panic!("input: {tokens:?}\nparser stopped early");
                };
                cp = feed(state, t);
            }
            match cp {
                Checkpoint::Accepted(got) => assert_eq!(got, want, "input: {tokens:?}"),
                _ => panic!("input: {tokens:?}\nnot accepted by `feed`"),
            }
        }
    }
}
